package com.bank.gridkw.service;

import com.bank.gridkw.trie.TrieNode;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Backtracking grid search driven by a trie of keywords.
public class GridKeywordService {
    private static final Logger log = Logger.getLogger(GridKeywordService.class.getName());

    public List<String> findKeywords(char[][] grid, List<String> words) {
        TrieNode root = new TrieNode();
        for (String w : words) {                    // build the trie of keywords
            TrieNode node = root;
            for (char c : w.toCharArray())
                node = node.children.computeIfAbsent(c, k -> new TrieNode());
            node.word = w;
        }
        List<String> found = new ArrayList<>();
        for (int r = 0; r < grid.length; r++)
            for (int c = 0; c < grid[0].length; c++)
                dfs(grid, r, c, root, found);
        log.info(() -> "Keywords found in grid = " + found);
        return found;
    }

    private void dfs(char[][] grid, int r, int c, TrieNode node, List<String> found) {
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length) return;
        char ch = grid[r][c];
        if (ch == '#') return;                       // visited on current path
        TrieNode child = node.children.get(ch);
        if (child == null) return;                   // prune: no keyword has this prefix
        if (child.word != null) {
            found.add(child.word);                   // a complete keyword ends here
            child.word = null;                       // avoid duplicate reports
        }
        grid[r][c] = '#';                            // mark visited
        dfs(grid, r + 1, c, child, found);
        dfs(grid, r - 1, c, child, found);
        dfs(grid, r, c + 1, child, found);
        dfs(grid, r, c - 1, child, found);
        grid[r][c] = ch;                             // restore for other paths
    }
}
