package com.bank.gridkw;

import com.bank.gridkw.service.GridKeywordService;
import java.util.List;
import java.util.logging.Logger;

public class GridKeywordApplication {
    private static final Logger log = Logger.getLogger(GridKeywordApplication.class.getName());

    public static void main(String[] args) {
        GridKeywordService service = new GridKeywordService();
        char[][] grid = {
            {'S', 'A', 'L'},
            {'X', 'R', 'A'},
            {'E', 'N', 'T'}
        };
        List<String> words = List.of("SAL", "RENT", "RAT");
        List<String> found = service.findKeywords(grid, words);
        log.info("Detected cheque keywords: " + found);
    }
}
